CREATE TABLE `User` (`id` VARCHAR(191) NOT NULL,`phone` VARCHAR(191) NULL,`email` VARCHAR(191) NULL,`passwordHash` VARCHAR(191) NULL,`role` ENUM('CUSTOMER','OWNER','PHARMACIST','DELIVERY') NOT NULL DEFAULT 'CUSTOMER',`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `User_phone_key` (`phone`),UNIQUE INDEX `User_email_key` (`email`),INDEX `User_role_idx` (`role`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Category` (`id` VARCHAR(191) NOT NULL,`name` VARCHAR(191) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `Category_name_key` (`name`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Medicine` (`id` VARCHAR(191) NOT NULL,`name` VARCHAR(191) NOT NULL,`brand` VARCHAR(191) NULL,`categoryId` VARCHAR(191) NOT NULL,`composition` VARCHAR(191) NULL,`details` JSON NULL,`imageUrl` VARCHAR(191) NULL,`mrp` DECIMAL(10,2) NOT NULL,`sellingPrice` DECIMAL(10,2) NOT NULL,`rxRequired` BOOLEAN NOT NULL DEFAULT false,`lowStockThreshold` INTEGER NOT NULL DEFAULT 3,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),INDEX `Medicine_name_idx` (`name`),CONSTRAINT `Medicine_categoryId_fkey` FOREIGN KEY (`categoryId`) REFERENCES `Category`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `MedicineCost` (`medicineId` VARCHAR(191) NOT NULL,`costPrice` DECIMAL(10,2) NOT NULL,`updatedAt` DATETIME(3) NOT NULL,PRIMARY KEY (`medicineId`),CONSTRAINT `MedicineCost_medicineId_fkey` FOREIGN KEY (`medicineId`) REFERENCES `Medicine`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Batch` (`id` VARCHAR(191) NOT NULL,`medicineId` VARCHAR(191) NOT NULL,`batchNumber` VARCHAR(191) NOT NULL,`quantity` INTEGER NOT NULL,`expiry` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),INDEX `Batch_medicineId_expiry_idx` (`medicineId`,`expiry`),CONSTRAINT `Batch_medicineId_fkey` FOREIGN KEY (`medicineId`) REFERENCES `Medicine`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `StockMovement` (`id` VARCHAR(191) NOT NULL,`batchId` VARCHAR(191) NOT NULL,`quantity` INTEGER NOT NULL,`reason` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),CONSTRAINT `StockMovement_batchId_fkey` FOREIGN KEY (`batchId`) REFERENCES `Batch`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Address` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`label` VARCHAR(191) NOT NULL,`line1` VARCHAR(191) NOT NULL,`line2` VARCHAR(191) NULL,`city` VARCHAR(191) NOT NULL,`pincode` VARCHAR(191) NOT NULL,`phone` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),INDEX `Address_userId_idx` (`userId`),CONSTRAINT `Address_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Prescription` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`privateObjectKey` VARCHAR(191) NOT NULL,`doctorName` VARCHAR(191) NOT NULL,`expiresAt` DATETIME(3) NULL,`approvedAt` DATETIME(3) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),INDEX `Prescription_userId_expiresAt_idx` (`userId`,`expiresAt`),CONSTRAINT `Prescription_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Order` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`status` ENUM('PENDING_VERIFICATION','APPROVED','PACKED','OUT_FOR_DELIVERY','DELIVERED','REJECTED') NOT NULL DEFAULT 'PENDING_VERIFICATION',`total` DECIMAL(10,2) NOT NULL,`prescriptionId` VARCHAR(191) NULL,`addressSnapshot` JSON NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),INDEX `Order_userId_createdAt_idx` (`userId`,`createdAt`),CONSTRAINT `Order_userId_fkey` FOREIGN KEY (`userId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `OrderItem` (`id` VARCHAR(191) NOT NULL,`orderId` VARCHAR(191) NOT NULL,`medicineId` VARCHAR(191) NOT NULL,`quantity` INTEGER NOT NULL,`unitPrice` DECIMAL(10,2) NOT NULL,`costSnapshot` DECIMAL(10,2) NOT NULL,`discount` DECIMAL(10,2) NOT NULL,PRIMARY KEY (`id`),CONSTRAINT `OrderItem_orderId_fkey` FOREIGN KEY (`orderId`) REFERENCES `Order`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `OrderStatusHistory` (`id` VARCHAR(191) NOT NULL,`orderId` VARCHAR(191) NOT NULL,`status` ENUM('PENDING_VERIFICATION','APPROVED','PACKED','OUT_FOR_DELIVERY','DELIVERED','REJECTED') NOT NULL,`reason` VARCHAR(191) NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),CONSTRAINT `OrderStatusHistory_orderId_fkey` FOREIGN KEY (`orderId`) REFERENCES `Order`(`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Offer` (`id` VARCHAR(191) NOT NULL,`type` ENUM('FESTIVAL','COMBO','PRODUCT_DISCOUNT','COUPON') NOT NULL,`title` VARCHAR(191) NOT NULL,`config` JSON NOT NULL,`startsAt` DATETIME(3) NULL,`endsAt` DATETIME(3) NULL,`active` BOOLEAN NOT NULL DEFAULT true,PRIMARY KEY (`id`),INDEX `Offer_type_active_startsAt_endsAt_idx` (`type`,`active`,`startsAt`,`endsAt`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Coupon` (`code` VARCHAR(191) NOT NULL,`offerId` VARCHAR(191) NOT NULL,`usageLimit` INTEGER NOT NULL,`perCustomerLimit` INTEGER NOT NULL,`expiresAt` DATETIME(3) NOT NULL,PRIMARY KEY (`code`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CouponRedemption` (`id` VARCHAR(191) NOT NULL,`couponCode` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`orderId` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),INDEX `CouponRedemption_couponCode_userId_idx` (`couponCode`,`userId`),CONSTRAINT `CouponRedemption_couponCode_fkey` FOREIGN KEY (`couponCode`) REFERENCES `Coupon`(`code`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `NotifyRequest` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`medicineId` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `NotifyRequest_userId_medicineId_key` (`userId`,`medicineId`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `DeviceToken` (`id` VARCHAR(191) NOT NULL,`userId` VARCHAR(191) NOT NULL,`token` VARCHAR(191) NOT NULL,`platform` VARCHAR(191) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `DeviceToken_userId_token_key` (`userId`,`token`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Broadcast` (`id` VARCHAR(191) NOT NULL,`message` VARCHAR(191) NOT NULL,`imageUrl` VARCHAR(191) NULL,`active` BOOLEAN NOT NULL DEFAULT true,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `Setting` (`key` VARCHAR(191) NOT NULL,`value` JSON NOT NULL,PRIMARY KEY (`key`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `AppConfig` (`id` INTEGER NOT NULL DEFAULT 1,`minSupportedVersion` VARCHAR(191) NOT NULL,`latestVersion` VARCHAR(191) NOT NULL,`storeUrl` VARCHAR(191) NULL,`whatsNew` VARCHAR(191) NULL,PRIMARY KEY (`id`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `AuditLog` (`id` VARCHAR(191) NOT NULL,`actorId` VARCHAR(191) NOT NULL,`action` VARCHAR(191) NOT NULL,`entityType` VARCHAR(191) NOT NULL,`entityId` VARCHAR(191) NULL,`metadata` JSON NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),INDEX `AuditLog_actorId_createdAt_idx` (`actorId`,`createdAt`)) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
